foreach(['sources','feed_items','jobs','ai_generations','logs','daily_usage','migration_journal']as$logical){$table=$wpdb->prefix.'wpnb_'.$logical;$status=$wpdb->get_row($wpdb->prepare('SHOW TABLE STATUS LIKE %s',$table),ARRAY_A);if(!$status||strtolower((string)($status['Engine']??''))!=='innodb')$errors[]='engine:'.$logical;}
